// LRUCache.hpp
#pragma once

#include <cstddef>
#include <functional>
#include <list>
#include <map>
#include <mutex>
#include <optional>

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {}

    std::optional<V> get(const K& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // Move to front to mark as recently used
        list_.splice(list_.begin(), list_, it->second);
        return it->second->second;
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            // Update existing key and mark as recently used
            list_.splice(list_.begin(), list_, it->second);
            it->second->second = value;
            return;
        }
        // Insert new key
        if (map_.size() >= capacity_) {
            // Evict least recently used (back of list)
            auto back = list_.back();
            map_.erase(back.first);
            list_.pop_back();
        }
        list_.push_front({key, value});
        map_[key] = list_.begin();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return map_.size();
    }

private:
    std::size_t capacity_;
    mutable std::mutex mutex_;
    // List of (key, value) pairs, front = most recently used
    std::list<std::pair<const K, V>> list_;
    // Map from key to iterator in list_
    std::map<K, typename std::list<std::pair<const K, V>>::iterator> map_;
};
