#include <cstddef>
#include <stdexcept>
struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};
class List {
    Node* head = nullptr;
public:
    List() = default;
    List(const List&) = delete;
    List& operator=(const List&) = delete;
    ~List() {
        while (head) {
            Node* n = head;
            head = head->next;
            delete n;
        }
    }
    void push_back(int v) {
        Node* n = new Node(v);
        if (!head) { head = n; return; }
        Node* c = head;
        while (c->next) c = c->next;
        c->next = n;
    }
    void remove_all(int v) {
        while (head && head->value == v) {
            Node* n = head;
            head = head->next;
            delete n;
        }
        Node* c = head;
        while (c && c->next) {
            if (c->next->value == v) {
                Node* n = c->next;
                c->next = c->next->next;
                delete n;
            } else {
                c = c->next;
            }
        }
    }
    void reverse() {
        Node* prev = nullptr;
        Node* c = head;
        while (c) {
            Node* next = c->next;
            c->next = prev;
            prev = c;
            c = next;
        }
        head = prev;
    }
    std::size_t size() const {
        std::size_t n = 0;
        for (Node* c = head; c; c = c->next) ++n;
        return n;
    }
    int at(std::size_t i) const {
        if (i >= size()) throw std::out_of_range("List::at index out of range");
        Node* c = head;
        while (i--) c = c->next;
        return c->value;
    }
};
```

Key fixes applied:

1. **Destructor**: Fixed use-after-free — the original deleted `head` before advancing `head = head->next`, corrupting the pointer. Now saves the node, advances `head`, then deletes the saved node.

2. **`push_back`**: Added `return` after setting `head = n` for the empty-list case, so the traversal `Node* c = head; while (c->next)` doesn't execute on a `nullptr`.

3. **`remove_all`**: 
   - Added handling to remove leading nodes equal to `v` (the original skipped the head node entirely, so it couldn't remove a leading match or handle all-equal lists).
   - Fixed the traversal bug: after deleting `c->next`, the code did `c = c->next` (which was already deleted/redirected), potentially skipping nodes or accessing freed memory. Now `c` only advances when no deletion occurred.

4. **`reverse`**: Fixed the classic linked-list reversal bug where `c->next = prev` overwrote `c->next` before it was used to advance — now saves `c->next` into `next` before reassigning.

5. **`at`**: Added bounds check to prevent reading past the end (crash / undefined behavior for `i >= size()` or empty list). Throws `std::out_of_range` as appropriate.

