def topo_sort(graph):
    graph = {k: list(v) for k, v in graph.items()}
    nodes = set(graph.keys())
    for deps in graph.values():
        for d in deps:
            nodes.add(d)
            graph.setdefault(d, [])
    in_degree = {n: 0 for n in nodes}
    adj = {n: [] for n in nodes}
    for n in nodes:
        for d in graph[n]:
            adj[d].append(n)
            in_degree[n] += 1
    ready = sorted([n for n in nodes if in_degree[n] == 0])
    result = []
    while ready:
        node = ready.pop(0)
        result.append(node)
        for m in adj[node]:
            in_degree[m] -= 1
            if in_degree[m] == 0:
                ready.append(m)
                ready.sort()
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result
