import csv
from collections import defaultdict

def summarize_sales(path):
    rows = 0
    skipped = 0
    total = 0.0
    by_region = defaultdict(float)
    product_rev = defaultdict(float)

    with open(path, newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            return {"rows": 0, "skipped": 0, "total": 0.0, "by_region": {}, "top_product": None}

        for row in reader:
            if len(row) < 5:
                skipped += 1
                continue
            date, region, product, qty_str, price_str = row[0], row[1], row[2], row[3], row[4]

            try:
                qty = int(qty_str)
            except (ValueError, TypeError):
                try:
                    qty = float(qty_str)
                except (ValueError, TypeError):
                    skipped += 1
                    continue

            try:
                price = float(price_str)
            except (ValueError, TypeError):
                skipped += 1
                continue

            if qty <= 0 or price < 0:
                skipped += 1
                continue

            rows += 1
            revenue = qty * price
            total += revenue
            by_region[region] += revenue
            product_rev[product] += revenue

        total = round(total, 2)
        by_region = {k: round(v, 2) for k, v in by_region.items()}

        top_product = None
        if product_rev:
            top_product = min(product_rev.keys(), key=lambda p: (-product_rev[p], p))

    return {
        "rows": rows,
        "skipped": skipped,
        "total": total,
        "by_region": dict(by_region),
        "top_product": top_product,
    }
