            throw new IllegalArgumentException("isbn already exists");
        }
        byIsbn[isbn] = new BookRecord(isbn, title, null, null);
    }

    public void borrow(String isbn, String member, LocalDate date) {
        BookRecord rec = byIsbn.get(isbn);
        if (rec == null) {
            throw new NoSuchElementException("isbn unknown");
        }
        if (rec.isBorrowed()) {
            throw new IllegalStateException("already borrowed");
        }
        rec.borrower = member;
        rec.borrowDate = date;
    }

    public void giveBack(String isbn) {
        BookRecord rec = byIsbn.get(isbn);
        if (rec == null) {
            throw new NoSuchElementException("isbn unknown");
        }
        if (!rec.isBorrowed()) {
            throw new IllegalStateException("not borrowed");
        }
        rec.borrower = null;
        rec.borrowDate = null;
    }

