        List<String> result = new ArrayList<String>();
        for (BookRecord rec : byIsbn.values()) {
            if (rec.isBorrowed() && rec.borrowDate != null) {
                int diff = today.compareTo(rec.borrowDate);
                if (diff > days) {
                    result.add(rec.title);
                }
            }
        }
